"use client";

import { useRef, useState, type ReactNode } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";

interface Source {
  n: number;
  title: string;
  domain: string;
  letter: string;
  tone: string;
}

type AnswerPart = { text?: string; cite?: number };

function ChevronIcon() {
  return (
    <svg viewBox="0 0 24 24" width="12" height="12" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
      <path d="m6 9 6 6 6-6" />
    </svg>
  );
}

export function Sources({
  answer,
  sources,
  defaultExpanded = true,
}: {
  /** Answer text interleaved with { cite: n } markers matching a source's `n`. */
  answer: AnswerPart[];
  sources: Source[];
  defaultExpanded?: boolean;
}) {
  const [expanded, setExpanded] = useState(defaultExpanded);
  const [activeId, setActiveId] = useState<number | null>(null);
  const cardRefs = useRef<Record<number, HTMLButtonElement | null>>({});
  const shouldReduceMotion = useReducedMotion();
  const panelId = "sources-panel";

  const focusSource = (n: number) => {
    setExpanded(true);
    setActiveId(n);
    requestAnimationFrame(() => cardRefs.current[n]?.focus());
  };

  const clearIfActive = (n: number) => setActiveId((a) => (a === n ? null : a));

  return (
    <div className="w-full max-w-md rounded-2xl border border-slate-200/70 bg-white/95 p-5 shadow-sm backdrop-blur-xl dark:border-white/10 dark:bg-neutral-950/80">
      <p className="text-sm leading-relaxed text-slate-600 dark:text-slate-300">
        {answer.map((part, i): ReactNode => {
          if (part.text !== undefined) return <span key={i}>{part.text}</span>;
          const n = part.cite as number;
          const source = sources.find((s) => s.n === n);
          if (!source) return null;
          const active = activeId === n;
          return (
            <button
              key={i}
              type="button"
              onMouseEnter={() => setActiveId(n)}
              onMouseLeave={() => clearIfActive(n)}
              onFocus={() => setActiveId(n)}
              onBlur={() => clearIfActive(n)}
              onClick={() => focusSource(n)}
              aria-label={`Jump to source ${n}: ${source.title}`}
              className={`relative -top-1 mx-0.5 inline-flex h-4 w-4 items-center justify-center rounded-full text-[10px] font-semibold transition-all focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 ${
                active
                  ? "scale-110 bg-emerald-700 text-white ring-2 ring-emerald-500/50"
                  : "bg-emerald-500/10 text-emerald-700 hover:bg-emerald-700 hover:text-white dark:bg-emerald-400/10 dark:text-emerald-400"
              }`}
            >
              {n}
            </button>
          );
        })}
      </p>

      <div className="mt-4">
        <button
          type="button"
          onClick={() => setExpanded((v) => !v)}
          aria-expanded={expanded}
          aria-controls={panelId}
          className="inline-flex items-center gap-2 rounded-full border border-slate-200/70 bg-black/[0.02] px-2 py-1 transition-colors hover:border-slate-300 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:border-white/10 dark:bg-white/[0.03] dark:hover:border-white/20"
        >
          <span className="flex -space-x-1.5">
            {sources.map((s) => (
              <span
                key={s.n}
                className={`flex h-5 w-5 items-center justify-center rounded-full text-[9px] font-semibold text-white ring-2 ring-white dark:ring-neutral-950 ${s.tone}`}
              >
                {s.letter}
              </span>
            ))}
          </span>
          <span className="text-xs font-medium text-slate-500 dark:text-slate-400">{sources.length} sources</span>
          <motion.span
            animate={{ rotate: expanded ? 180 : 0 }}
            transition={{ duration: 0.35, ease: [0.22, 1, 0.36, 1] }}
            className="text-slate-400"
          >
            <ChevronIcon />
          </motion.span>
        </button>

        <AnimatePresence initial={false}>
          {expanded && (
            <motion.div
              id={panelId}
              role="region"
              aria-label="Sources"
              initial={shouldReduceMotion ? { opacity: 0 } : { height: 0, opacity: 0 }}
              animate={shouldReduceMotion ? { opacity: 1 } : { height: "auto", opacity: 1 }}
              exit={shouldReduceMotion ? { opacity: 0 } : { height: 0, opacity: 0 }}
              transition={shouldReduceMotion ? { duration: 0.15 } : { height: { duration: 0.45, ease: [0.22, 1, 0.36, 1] }, opacity: { duration: 0.3, ease: [0.22, 1, 0.36, 1] } }}
              className="overflow-hidden"
            >
              <motion.ul
                initial={shouldReduceMotion ? undefined : { y: -10 }}
                animate={{ y: 0 }}
                transition={shouldReduceMotion ? { duration: 0 } : { duration: 0.4, ease: [0.22, 1, 0.36, 1], delay: 0.08 }}
                className="mt-2 flex flex-col gap-1"
                role="list"
              >
                {sources.map((s, i) => {
                  const active = activeId === s.n;
                  return (
                    <motion.li
                      key={s.n}
                      initial={shouldReduceMotion ? undefined : { opacity: 0, y: -6 }}
                      animate={{ opacity: 1, y: 0 }}
                      transition={shouldReduceMotion ? { duration: 0 } : { duration: 0.3, delay: 0.12 + i * 0.05, ease: [0.22, 1, 0.36, 1] }}
                    >
                      <button
                        ref={(el) => {
                          cardRefs.current[s.n] = el;
                        }}
                        type="button"
                        onMouseEnter={() => setActiveId(s.n)}
                        onMouseLeave={() => clearIfActive(s.n)}
                        onFocus={() => setActiveId(s.n)}
                        onBlur={() => clearIfActive(s.n)}
                        onClick={() => setActiveId(s.n)}
                        className={`relative flex w-full items-center gap-3 overflow-hidden rounded-xl border px-3 py-2.5 text-left transition-colors focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 ${
                          active
                            ? "border-emerald-400/50 bg-emerald-500/5 dark:border-emerald-400/30 dark:bg-emerald-400/5"
                            : "border-transparent hover:border-slate-200 hover:bg-black/[0.02] dark:hover:border-white/10 dark:hover:bg-white/[0.03]"
                        }`}
                      >
                        {!shouldReduceMotion && (
                          <AnimatePresence>
                            {active && (
                              <motion.span
                                key={`pulse-${s.n}`}
                                aria-hidden
                                className="absolute inset-0 rounded-xl border-2 border-emerald-400/60"
                                initial={{ opacity: 0.7, scale: 0.98 }}
                                animate={{ opacity: 0, scale: 1.02 }}
                                transition={{ duration: 0.5, ease: [0.16, 1, 0.3, 1] }}
                              />
                            )}
                          </AnimatePresence>
                        )}
                        <span className={`flex h-8 w-8 shrink-0 items-center justify-center rounded-full text-xs font-semibold text-white ${s.tone}`}>
                          {s.letter}
                        </span>
                        <span className="min-w-0 flex-1">
                          <span className="block truncate text-sm font-medium text-slate-800 dark:text-slate-100">{s.title}</span>
                          <span className="block truncate text-xs text-slate-400 dark:text-slate-500">{s.domain}</span>
                        </span>
                        <span
                          className={`inline-flex h-5 w-5 shrink-0 items-center justify-center rounded-full text-[10px] font-semibold ${
                            active ? "bg-emerald-700 text-white" : "bg-black/5 text-slate-500 dark:bg-white/10 dark:text-slate-400"
                          }`}
                        >
                          {s.n}
                        </span>
                      </button>
                    </motion.li>
                  );
                })}
              </motion.ul>
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </div>
  );
}
